/**
 ******************************************************************************
 * @file    bq34z100.c
 * TEAM CODE (owner: Brendon - battery monitor and USB-C MSC) - written by the BJT2 team, not generated by STM32CubeMX.
 * @brief   BQ34Z100-G1 fuel-gauge driver — hardware-independent PD5b refactor.
 *
 * Owner: Brendon Bone. Same command set and sequences as the PD3 driver; all
 * bus traffic now goes through the injected BQ_Bus (no STM32 HAL), so the
 * whole file runs under host-side unit tests.
 *
 * No task of its own: on the board every call comes from BrendonTask (the
 * 1 Hz poll in battery_monitor.c, the debug screen's temperature read) or
 * from Brendon_Init before the kernel starts. Command codes and the words
 * (standard command, Control(), data flash): see bq34z100.h.
 *
 * How one reading works (bq_read_u16):
 *   1. bus->mem_read: write the command code, read 2 bytes back
 *   2. join them little-endian (low byte first)
 *   3. a signed value (a current) is the same 16 bits read as int16_t
 * A data-flash write (BQ34Z100_WriteDataFlashU16): unseal -> choose the
 * block -> read its 32 bytes -> change 2 of them -> write those back ->
 * write the new checksum, which makes the gauge store the block (150 ms).
 * Generative AI was used to assist in the refactoring process.
 ******************************************************************************
 */
#include "bq34z100.h"

#include <stddef.h>

/* -------------------------------------------------------------------------- */
/* Low-level read/write helpers                                                */
/* -------------------------------------------------------------------------- */

/**
 * @brief Validate that @p bus provides the operations needed for reads.
 * @return BQ_OK when bus and bus->mem_read are usable.
 */
static BQ_Status bq_bus_readable(const BQ_Bus *bus)
{
    return (bus != NULL && bus->mem_read != NULL) ? BQ_OK : BQ_ERROR;
}

/**
 * @brief Validate that @p bus provides the operations needed for writes.
 * @return BQ_OK when bus and bus->mem_write are usable.
 */
static BQ_Status bq_bus_writable(const BQ_Bus *bus)
{
    return (bus != NULL && bus->mem_write != NULL) ? BQ_OK : BQ_ERROR;
}

/**
 * @brief Delay helper: forwards to the injected delay if one was provided.
 *
 * The 2 ms settle and 150 ms flash-commit pauses matter on real hardware; a
 * bus without delay_ms simply proceeds (fine for tests and fast masters).
 */
static void bq_delay(const BQ_Bus *bus, uint32_t ms)
{
    if (bus != NULL && bus->delay_ms != NULL) {
        bus->delay_ms(bus->ctx, ms);
    }
}

/**
 * @brief Read the two bytes at @p cmd and combine them little-endian.
 * @param bus Injected bus operations.
 * @param cmd Command/register code to read from.
 * @param out Receives the assembled 16-bit value.
 */
static BQ_Status bq_read_u16(const BQ_Bus *bus, uint8_t cmd, uint16_t *out)
{
    uint8_t bytes[2] = {0};

    if (out == NULL || bq_bus_readable(bus) != BQ_OK) {
        return BQ_ERROR;
    }

    if (bus->mem_read(bus->ctx, cmd, bytes, (uint16_t)sizeof(bytes)) != 0) {
        return BQ_ERROR;
    }

    *out = (uint16_t)bytes[0] | ((uint16_t)bytes[1] << 8);
    return BQ_OK;
}

/**
 * @brief Read the single byte stored at @p cmd.
 * @param bus Injected bus operations.
 * @param cmd Command/register code to read from.
 * @param out Receives the byte.
 */
static BQ_Status bq_read_u8(const BQ_Bus *bus, uint8_t cmd, uint8_t *out)
{
    if (out == NULL || bq_bus_readable(bus) != BQ_OK) {
        return BQ_ERROR;
    }

    if (bus->mem_read(bus->ctx, cmd, out, 1U) != 0) {
        return BQ_ERROR;
    }

    return BQ_OK;
}

/**
 * @brief Write a 16-bit value to @p cmd, low byte first (runtime LE order).
 *
 * Used for Control() subcommands and to set up data-flash access.
 */
static BQ_Status bq_write_u16(const BQ_Bus *bus, uint8_t cmd, uint16_t value)
{
    uint8_t bytes[2];

    if (bq_bus_writable(bus) != BQ_OK) {
        return BQ_ERROR;
    }

    bytes[0] = (uint8_t)(value & 0xFFU);
    bytes[1] = (uint8_t)((value >> 8) & 0xFFU);

    if (bus->mem_write(bus->ctx, cmd, bytes, (uint16_t)sizeof(bytes)) != 0) {
        return BQ_ERROR;
    }

    return BQ_OK;
}

/**
 * @brief Write a single byte to @p cmd (data-flash select registers).
 */
static BQ_Status bq_write_u8(const BQ_Bus *bus, uint8_t cmd, uint8_t value)
{
    if (bq_bus_writable(bus) != BQ_OK) {
        return BQ_ERROR;
    }

    if (bus->mem_write(bus->ctx, cmd, &value, 1U) != 0) {
        return BQ_ERROR;
    }

    return BQ_OK;
}

/* -------------------------------------------------------------------------- */
/* Basic setup                                                                 */
/* -------------------------------------------------------------------------- */

/**
 * @brief Probe the gauge by pinging its address (no data read).
 *
 * Makes up to BQ34Z100_INIT_PROBE_ATTEMPTS attempts, mirroring the 3 trials
 * the PD3 driver requested from HAL_I2C_IsDeviceReady, so a gauge that is
 * momentarily busy still gets detected.
 */
BQ_Status BQ34Z100_Init(const BQ_Bus *bus)
{
    uint8_t attempt;

    if (bus == NULL || bus->is_ready == NULL) {
        return BQ_ERROR;
    }

    for (attempt = 0U; attempt < BQ34Z100_INIT_PROBE_ATTEMPTS; attempt++) {
        if (bus->is_ready(bus->ctx) == 0) {
            return BQ_OK;
        }
    }

    return BQ_ERROR;
}

