/**
 * @brief Read UpdateStatus from data flash (subclass 82, offset 4).
 *
 * Sequence: BlockDataControl=0 -> DataFlashClass=82 -> DataFlashBlock=0
 * -> settle -> read BlockData()+4. Confirms whether the chemistry profile
 * has actually LEARNED (0x06) rather than just guessing.
 */
BQ_Status BQ34Z100_ReadUpdateStatus(const BQ_Bus *bus, uint8_t *out_status)
{
    if (out_status == NULL ||
        bq_bus_readable(bus) != BQ_OK || bq_bus_writable(bus) != BQ_OK) {
        return BQ_ERROR;
    }

    /* Enable block data-flash access: write 0x00 to BlockDataControl (0x61). */
    if (bq_write_u8(bus, BQ34Z100_CMD_BLOCK_DATA_CONTROL, 0x00U) != BQ_OK) {
        return BQ_ERROR;
    }

    /* Select Data Flash subclass 82 (Gas Gauging / State). */
    if (bq_write_u8(bus, BQ34Z100_CMD_DATA_FLASH_CLASS,
                    (uint8_t)BQ34Z100_DF_CLASS_STATE) != BQ_OK) {
        return BQ_ERROR;
    }

    /* Select the block containing offset 4 (block 0). */
    if (bq_write_u8(bus, BQ34Z100_CMD_DATA_FLASH_BLOCK,
                    (uint8_t)(BQ34Z100_DF_OFFSET_UPDATE_STATUS / 32U)) != BQ_OK) {
        return BQ_ERROR;
    }

    /* Give the gauge a short time to load the selected data-flash block. */
    bq_delay(bus, 2U);

    /* Read one byte from BlockData(): 0x40 + (offset % 32). */
    {
        const uint8_t block_offset = (uint8_t)(BQ34Z100_DF_OFFSET_UPDATE_STATUS % 32U);
        const uint8_t read_address = (uint8_t)(BQ34Z100_CMD_BLOCK_DATA_START + block_offset);

        if (bus->mem_read(bus->ctx, read_address, out_status, 1U) != 0) {
            return BQ_ERROR;
        }
    }

    return BQ_OK;
}

