/** @brief Send a Control() subcommand (16-bit, little-endian) to 0x00. */
BQ_Status BQ34Z100_ControlCommand(const BQ_Bus *bus, uint16_t subcommand)
{
    return bq_write_u16(bus, BQ34Z100_CMD_CONTROL, subcommand);
}

/**
 * @brief Send a Control() subcommand, then read back the 16-bit reply.
 *
 * The 2 ms settle gives the gauge time to place the response into
 * Control() 0x00/0x01 — usually faster, but 2 ms is safe for polled code.
 */
BQ_Status BQ34Z100_ControlRead(const BQ_Bus *bus,
                               uint16_t subcommand,
                               uint16_t *out_word)
{
    if (out_word == NULL) {
        return BQ_ERROR;
    }

    if (BQ34Z100_ControlCommand(bus, subcommand) != BQ_OK) {
        return BQ_ERROR;
    }

    bq_delay(bus, 2U);

    return bq_read_u16(bus, BQ34Z100_CMD_CONTROL, out_word);
}

/** @brief Read the gauge's ControlStatus() word. */
BQ_Status BQ34Z100_ReadControlStatus(const BQ_Bus *bus, uint16_t *out_status)
{
    return BQ34Z100_ControlRead(bus, BQ34Z100_CTRL_CONTROL_STATUS, out_status);
}

