/** @brief Unseal the gauge with the two-part key (2 ms between words). */
BQ_Status BQ34Z100_Unseal(const BQ_Bus *bus, uint16_t key1, uint16_t key2)
{
    if (BQ34Z100_ControlCommand(bus, key1) != BQ_OK) {
        return BQ_ERROR;
    }

    bq_delay(bus, 2U);

    if (BQ34Z100_ControlCommand(bus, key2) != BQ_OK) {
        return BQ_ERROR;
    }

    bq_delay(bus, 2U);

    return BQ_OK;
}

/* -------------------------------------------------------------------------- */
/* Data flash write                                                            */
/* -------------------------------------------------------------------------- */

/**
 * @brief Write a 16-bit value into data flash at (subclass, offset).
 *
 * Unseals the gauge, reads the 32-byte block the value lives in, patches the
 * two target bytes (big-endian), writes them back, and commits with a fresh
 * checksum. The checksum write is what moves the block from gauge RAM into
 * flash, so it MUST be last and MUST be given the 150 ms commit time.
 */
BQ_Status BQ34Z100_WriteDataFlashU16(const BQ_Bus *bus,
                                     uint8_t subclass,
                                     uint8_t offset,
                                     uint16_t value)
{
    const uint8_t block_num    = (uint8_t)(offset / 32U);
    const uint8_t off_in_block = (uint8_t)(offset % 32U);
    uint8_t block[32];
    uint16_t sum;
    uint8_t checksum;
    int i;

    if (bq_bus_readable(bus) != BQ_OK || bq_bus_writable(bus) != BQ_OK) {
        return BQ_ERROR;
    }

    /* The offset+1 byte must still live inside the same 32-byte block. */
    if (off_in_block > 30U) {
        return BQ_ERROR;
    }

    /* 1) Unseal (no-op if already unsealed). */
    if (BQ34Z100_Unseal(bus,
                        BQ34Z100_DEFAULT_UNSEAL_KEY1,
                        BQ34Z100_DEFAULT_UNSEAL_KEY2) != BQ_OK) {
        return BQ_ERROR;
    }

    /* 2) Enable BlockDataControl: write 0x00 to register 0x61. */
    if (bq_write_u8(bus, BQ34Z100_CMD_BLOCK_DATA_CONTROL, 0x00U) != BQ_OK) {
        return BQ_ERROR;
    }
    bq_delay(bus, 2U);

    /* 3) Select the subclass. */
    if (bq_write_u8(bus, BQ34Z100_CMD_DATA_FLASH_CLASS, subclass) != BQ_OK) {
        return BQ_ERROR;
    }
    bq_delay(bus, 2U);

    /* 4) Select the block within the subclass. */
    if (bq_write_u8(bus, BQ34Z100_CMD_DATA_FLASH_BLOCK, block_num) != BQ_OK) {
        return BQ_ERROR;
    }
    bq_delay(bus, 2U);

    /* 5) Read the existing 32-byte block. */
    if (bus->mem_read(bus->ctx, BQ34Z100_CMD_BLOCK_DATA_START,
                      block, (uint16_t)sizeof(block)) != 0) {
        return BQ_ERROR;
    }

    /* 6) Patch the two target bytes in big-endian order. */
    block[off_in_block]      = (uint8_t)((value >> 8) & 0xFFU);
    block[off_in_block + 1U] = (uint8_t)(value & 0xFFU);

    /* 7) Write the modified bytes back. */
    if (bus->mem_write(bus->ctx,
                       (uint8_t)(BQ34Z100_CMD_BLOCK_DATA_START + off_in_block),
                       &block[off_in_block], 2U) != 0) {
        return BQ_ERROR;
    }
    bq_delay(bus, 2U);

    /* 8) Recompute the block checksum: 0xFF - (sum mod 256). */
    sum = 0U;
    for (i = 0; i < 32; i++) {
        sum = (uint16_t)(sum + block[i]);
    }
    checksum = (uint8_t)(0xFFU - (uint8_t)(sum & 0xFFU));

    /* 9) Commit by writing the new checksum (must be last; needs 150 ms). */
    if (bq_write_u8(bus, BQ34Z100_CMD_BLOCK_DATA_CHECKSUM, checksum) != BQ_OK) {
        return BQ_ERROR;
    }
    bq_delay(bus, 150U);   /* flash write time */

    return BQ_OK;
}

/**
 * @brief Write the battery's design capacity into data flash.
 *
 * BQ34Z100-G1: subclass 48 ("Data"), offset 21, 2 bytes big-endian.
 * Confirmed empirically via the data-flash scan on this gauge.
 */
BQ_Status BQ34Z100_WriteDesignCapacity_mAh(const BQ_Bus *bus, uint16_t mAh)
{
    return BQ34Z100_WriteDataFlashU16(bus, 48U, 21U, mAh);
}

/**
 * @brief Read a whole 32-byte data-flash block into @p out_block.
 *
 * BlockDataControl=0 -> subclass -> block -> settle -> read 32 bytes at 0x40.
 * Does not unseal.
 */
BQ_Status BQ34Z100_ReadDataFlashBlock(const BQ_Bus *bus,
                                      uint8_t subclass,
                                      uint8_t block_num,
                                      uint8_t out_block[32])
{
    if (out_block == NULL ||
        bq_bus_readable(bus) != BQ_OK || bq_bus_writable(bus) != BQ_OK) {
        return BQ_ERROR;
    }

    /* BlockDataControl = 0 (data-flash mode). */
    if (bq_write_u8(bus, BQ34Z100_CMD_BLOCK_DATA_CONTROL, 0x00U) != BQ_OK) {
        return BQ_ERROR;
    }
    bq_delay(bus, 2U);

    if (bq_write_u8(bus, BQ34Z100_CMD_DATA_FLASH_CLASS, subclass) != BQ_OK) {
        return BQ_ERROR;
    }
    bq_delay(bus, 2U);

    if (bq_write_u8(bus, BQ34Z100_CMD_DATA_FLASH_BLOCK, block_num) != BQ_OK) {
        return BQ_ERROR;
    }
    bq_delay(bus, 2U);

    if (bus->mem_read(bus->ctx, BQ34Z100_CMD_BLOCK_DATA_START,
                      out_block, 32U) != 0) {
        return BQ_ERROR;
    }

    return BQ_OK;
}
